-- PRODUCT STUDIO AI: commercial multi-user foundation
-- Cloudflare D1 / SQLite. Apply only after creating and binding a D1 database.
-- IDs are generated by the application (UUID/ULID); timestamps are UTC Unix seconds.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL COLLATE NOCASE UNIQUE,
  display_name TEXT NOT NULL DEFAULT '',
  auth_provider TEXT NOT NULL DEFAULT 'managed',
  auth_subject TEXT,
  role TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer','admin')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  last_login_at INTEGER,
  CHECK (length(email) BETWEEN 3 AND 254)
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_auth_identity
  ON users(auth_provider, auth_subject) WHERE auth_subject IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_users_status_created ON users(status, created_at);

-- Store only a hash of opaque session tokens, never the bearer token itself.
CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  revoked_at INTEGER,
  user_agent_hint TEXT,
  CHECK (expires_at > created_at)
);
CREATE INDEX IF NOT EXISTS idx_sessions_user_expiry ON sessions(user_id, expires_at);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);

CREATE TABLE IF NOT EXISTS products (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  main_asset_id TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  archived_at INTEGER,
  UNIQUE (id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_products_owner_updated ON products(user_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  product_id TEXT REFERENCES products(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','queued','processing','completed','failed','archived')),
  prompt TEXT NOT NULL DEFAULT '',
  settings_json TEXT NOT NULL DEFAULT '{}',
  export_preset TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  archived_at INTEGER,
  UNIQUE (id, user_id),
  FOREIGN KEY (product_id, user_id) REFERENCES products(id, user_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_projects_owner_updated ON projects(user_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_projects_product ON projects(product_id);

-- Metadata lives in D1; binary media belongs in private R2 buckets.
CREATE TABLE IF NOT EXISTS assets (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,
  product_id TEXT REFERENCES products(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('product_image','source_video','generated_video','thumbnail','other')),
  r2_key TEXT NOT NULL UNIQUE,
  content_type TEXT NOT NULL,
  byte_size INTEGER NOT NULL CHECK (byte_size >= 0),
  checksum_sha256 TEXT,
  width INTEGER,
  height INTEGER,
  duration_seconds REAL,
  created_at INTEGER NOT NULL,
  deleted_at INTEGER,
  CHECK (project_id IS NOT NULL OR product_id IS NOT NULL),
  UNIQUE (id, user_id),
  FOREIGN KEY (project_id, user_id) REFERENCES projects(id, user_id) ON DELETE CASCADE,
  FOREIGN KEY (product_id, user_id) REFERENCES products(id, user_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_assets_owner_created ON assets(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_assets_project ON assets(project_id);
CREATE INDEX IF NOT EXISTS idx_assets_product ON assets(product_id);

CREATE TABLE IF NOT EXISTS product_images (
  product_id TEXT NOT NULL,
  asset_id TEXT NOT NULL UNIQUE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)),
  created_at INTEGER NOT NULL,
  PRIMARY KEY (product_id, asset_id),
  FOREIGN KEY (product_id, user_id) REFERENCES products(id, user_id) ON DELETE CASCADE,
  FOREIGN KEY (asset_id, user_id) REFERENCES assets(id, user_id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_product_images_one_primary
  ON product_images(product_id) WHERE is_primary = 1;
CREATE INDEX IF NOT EXISTS idx_product_images_order ON product_images(product_id, sort_order);

CREATE TABLE IF NOT EXISTS generations (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
  provider TEXT NOT NULL DEFAULT 'runway',
  provider_task_id TEXT,
  model TEXT NOT NULL,
  resolution TEXT,
  aspect_ratio TEXT,
  duration_seconds INTEGER NOT NULL CHECK (duration_seconds BETWEEN 1 AND 60),
  status TEXT NOT NULL CHECK (status IN ('queued','processing','succeeded','failed','cancelled')),
  prompt_snapshot TEXT NOT NULL,
  estimated_credits INTEGER NOT NULL DEFAULT 0 CHECK (estimated_credits >= 0),
  charged_credits INTEGER NOT NULL DEFAULT 0 CHECK (charged_credits >= 0),
  error_code TEXT,
  error_message TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  completed_at INTEGER,
  UNIQUE(provider, provider_task_id),
  UNIQUE(id, user_id),
  FOREIGN KEY (project_id, user_id) REFERENCES projects(id, user_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_generations_owner_created ON generations(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_generations_status_updated ON generations(status, updated_at);

-- Append-only ledger. Balance is calculated from entries; never trust a client-supplied balance.
CREATE TABLE IF NOT EXISTS credit_ledger (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  generation_id TEXT REFERENCES generations(id) ON DELETE SET NULL,
  entry_type TEXT NOT NULL CHECK (entry_type IN ('grant','purchase','reservation','charge','refund','adjustment','expiry')),
  amount INTEGER NOT NULL CHECK (amount <> 0),
  idempotency_key TEXT UNIQUE,
  description TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  FOREIGN KEY (generation_id, user_id) REFERENCES generations(id, user_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_credit_ledger_user_created ON credit_ledger(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_ledger_generation ON credit_ledger(generation_id);

CREATE TABLE IF NOT EXISTS plans (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  monthly_price_minor INTEGER NOT NULL CHECK (monthly_price_minor >= 0),
  currency TEXT NOT NULL DEFAULT 'EUR',
  monthly_credits INTEGER NOT NULL CHECK (monthly_credits >= 0),
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS subscriptions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  plan_id TEXT NOT NULL REFERENCES plans(id),
  provider TEXT NOT NULL,
  provider_customer_id TEXT,
  provider_subscription_id TEXT UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('trialing','active','past_due','cancelled','expired')),
  current_period_start INTEGER,
  current_period_end INTEGER,
  cancel_at_period_end INTEGER NOT NULL DEFAULT 0 CHECK (cancel_at_period_end IN (0,1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_subscriptions_user_status ON subscriptions(user_id, status);

CREATE TABLE IF NOT EXISTS payment_events (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  provider_event_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  processed_at INTEGER,
  received_at INTEGER NOT NULL,
  UNIQUE(provider, provider_event_id)
);

CREATE TABLE IF NOT EXISTS audit_log (
  id TEXT PRIMARY KEY,
  actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  target_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_target_created ON audit_log(target_user_id, created_at DESC);


-- Credit history is immutable. Account deletion must anonymize users with
-- financial history rather than erase the ledger needed for reconciliation.
CREATE TRIGGER IF NOT EXISTS trg_credit_ledger_no_update
BEFORE UPDATE ON credit_ledger
BEGIN
  SELECT RAISE(ABORT, 'credit_ledger is immutable');
END;

CREATE TRIGGER IF NOT EXISTS trg_credit_ledger_no_delete
BEFORE DELETE ON credit_ledger
BEGIN
  SELECT RAISE(ABORT, 'credit_ledger is immutable');
END;
